package com.rustyvault.legacy;

import com.rustyvault.CustomerDirectory;
import java.sql.*;
import java.util.*;
import java.util.stream.Collectors;

public class LegacyCustomerDirectory implements CustomerDirectory {
    private final Connection conn;

    public LegacyCustomerDirectory(Connection conn) {
        this.conn = conn;
    }

    private long validateId(String id) {
        if (id == null || !id.matches("\\d{1,18}")) throw new IllegalArgumentException("Invalid ID");
        return Long.parseLong(id);
    }

    private long validateAmount(String amount) {
        if (amount == null || !amount.matches("\\d{1,18}")) throw new IllegalArgumentException("Invalid Amount");
        return Long.parseLong(amount);
    }

    @Override
    public long addCustomer(String name, String city, long balanceCents) {
        if (name == null || name.isBlank() || city == null || city.isBlank() || balanceCents < 0) {
            throw new IllegalArgumentException("Invalid input");
        }
        try (PreparedStatement ps = conn.prepareStatement(
                "INSERT INTO customer (name, city, balance_cents) VALUES (?, ?, ?)", Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, name);
            ps.setString(2, city);
            ps.setLong(3, balanceCents);
            ps.executeUpdate();
            try (ResultSet rs = ps.getGeneratedKeys()) {
                rs.next();
                return rs.getLong(1);
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }

    @Override
    public List<String> findByName(String name) {
        if (name == null) throw new IllegalArgumentException("Invalid name");
        return executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE name = ? ORDER BY id", 
            ps -> ps.setString(1, name));
    }

    @Override
    public List<String> searchByNamePrefix(String prefix) {
        if (prefix == null) throw new IllegalArgumentException("Invalid prefix");
        String escaped = prefix.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
        return executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE UPPER(name) LIKE UPPER(?) ESCAPE '\\' ORDER BY id", 
            ps -> ps.setString(1, escaped + "%"));
    }

    @Override
    public List<String> list(String sortBy, boolean descending) {
        Set<String> valid = Set.of("id", "name", "city", "balance");
        if (!valid.contains(sortBy)) throw new IllegalArgumentException("Invalid sort key");
        String col = "balance".equals(sortBy) ? "balance_cents" : sortBy;
        String sql = "SELECT id, name, city, balance_cents FROM customer ORDER BY " + col + (descending ? " DESC" : " ASC") + ", id ASC";
        return executeQuery(sql, ps -> {});
    }

    @Override
    public String getById(String id) {
        long numericId = validateId(id);
        List<String> res = executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE id = ?", ps -> ps.setLong(1, numericId));
        return res.isEmpty() ? null : res.get(0);
    }

    @Override
    public List<String> findByIds(List<String> ids) {
        if (ids == null) throw new IllegalArgumentException("Null list");
        if (ids.isEmpty()) return List.of();
        List<Long> numericIds = ids.stream().map(this::validateId).collect(Collectors.toList());
        String placeholders = ids.stream().map(i -> "?").collect(Collectors.joining(","));
        return executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE id IN (" + placeholders + ") ORDER BY id", ps -> {
            for (int i = 0; i < numericIds.size(); i++) ps.setLong(i + 1, numericIds.get(i));
        });
    }

    @Override
    public List<String> richerThan(String minBalanceCents) {
        long amt = validateAmount(minBalanceCents);
        return executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE balance_cents > ? ORDER BY id", ps -> ps.setLong(1, amt));
    }

    @Override
    public List<String> sameCityAs(String id) {
        String row = getById(id);
        if (row == null) throw new IllegalArgumentException("Unknown ID");
        String city = row.split("\\|")[2];
        return executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE city = ? AND id <> ? ORDER BY id", ps -> {
            ps.setString(1, city);
            ps.setLong(2, validateId(id));
        });
    }

    @Override
    public int deleteByCity(String city) {
        if (city == null) throw new IllegalArgumentException("Invalid city");
        try (PreparedStatement ps = conn.prepareStatement("DELETE FROM customer WHERE city = ?")) {
            ps.setString(1, city);
            return ps.executeUpdate();
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }

    @Override
    public int count() {
        return executeQuery("SELECT id, name, city, balance_cents FROM customer", ps -> {}).size();
    }

    private List<String> executeQuery(String sql, StatementPreparer prep) {
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            prep.prepare(ps);
            try (ResultSet rs = ps.executeQuery()) {
                List<String> res = new ArrayList<>();
                while (rs.next()) res.add(rs.getLong(1) + "|" + rs.getString(2) + "|" + rs.getString(3) + "|" + rs.getLong(4));
                return res;
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e);
        }
    }

    private interface StatementPreparer { void prepare(PreparedStatement ps) throws SQLException; }
}
