    public List<String> richerThan(String minBalanceCents) {
        validateNumeric(minBalanceCents);
        return executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE balance_cents > ? ORDER BY id", ps -> ps.setLong(1, Long.parseLong(minBalanceCents)));
    }

    @Override
    public List<String> sameCityAs(String id) {
        validateNumeric(id);
        String row = getById(id);
        if (row == null) throw new IllegalArgumentException("Unknown ID");
        String city = row.split("\\|")[2];
        return executeQuery("SELECT id, name, city, balance_cents FROM customer WHERE city = ? AND id <> ? ORDER BY id", ps -> {
            ps.setString(1, city);
            ps.setLong(2, Long.parseLong(id));
        });
    }

    @Override
    public int deleteByCity(String city) {
        if (city == null) throw new IllegalArgumentException("Invalid city");
        try (PreparedStatement ps = conn.prepareStatement("DELETE FROM customer WHERE city = ?")) {
            ps.setString(1, city);
            return ps.executeUpdate();
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR", e);
        }
    }

    @Override
    public int count() {
        try (Statement st = conn.createStatement(); ResultSet rs = st.executeQuery("SELECT COUNT(*) FROM customer")) {
            return rs.next() ? rs.getInt(1) : 0;
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR", e);
        }
    }

    private List<String> executeQuery(String sql, StatementPreparer prep) {
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            prep.prepare(ps);
            try (ResultSet rs = ps.executeQuery()) {
                List<String> res = new ArrayList<>();
                while (rs.next()) {
                    res.add(rs.getLong(1) + "|" + rs.getString(2) + "|" + rs.getString(3) + "|" + rs.getLong(4));
                }
                return res;
            }
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR", e);
        }
    }

    private interface StatementPreparer { void prepare(PreparedStatement ps) throws SQLException; }
